function q(string $sql,array $p=[]): array { global $pdo; $s=$pdo->prepare($sql); $s->execute($p); return $s->fetchAll(); }
function one(string $sql,array $p=[]): ?array { $r=q($sql,$p); return $r[0]??null; }
